// ==UserScript==
// @name         Hide Figma Make Preview Header
// @version      1.0
// @author       Vivian Klein
// @description  Hides FigMake Preview Header in Full Page View
// @match        https://www.figma.com/make/*
// @icon         data:image/png;base64,
// @grant        none
// @run-at       document-end
// ==/UserScript==

(function () {
    "use strict";

    function hideElement() {
        const el =
            document
                .querySelector('[data-testid="figmake-full-view"]')
                ?.childNodes[0]?.childNodes[0]?.childNodes[0];

        if (el) el.style.display = "none";
    }

    // a) Run once when the page is loaded (document-end ensures DOM is ready)
    hideElement();

    // b) Re-run whenever the DOM tree changes
    const observer = new MutationObserver(() => hideElement());

    observer.observe(document.body, {
        childList: true, // watch for added/removed nodes
        subtree: true,   // including all descendants
    });
})();
